function App() {
  const [count, setCount] = useState(0);
  const [log, setLog] = useState([]);

  // Stable reference: only changes if category/sort change
  const options = useMemo(() => ({ category: 'books', sort: 'asc' }), []);

  useEffect(() => {
    setLog(l => [...l, 'Fetching for ' + options.category]);
  }, [options]); // now runs once, because options reference is stable

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setCount(c => c + 1)}>render ({count})</button>
      <p>effect runs: {log.length}</p>
    </div>
  );
}

function App() {
  const [threshold, setThreshold] = useState(50);
  const [dark, setDark] = useState(false);
  const numbers = useMemo(() => Array.from({ length: 10000 }, (_, i) => i % 100), []);

  const average = useMemo(() => {
    const above = numbers.filter(n => n > threshold);
    if (above.length === 0) return 0;
    return above.reduce((a, b) => a + b, 0) / above.length;
  }, [numbers, threshold]);

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16, background: dark ? '#222' : '#fff', color: dark ? '#eee' : '#111' }}>
      <p>Avg above {threshold}: {average.toFixed(2)}</p>
      <input type="range" min="0" max="99" value={threshold} onChange={e => setThreshold(Number(e.target.value))} />
      <button onClick={() => setDark(d => !d)} style={{ marginLeft: 8 }}>toggle theme</button>
    </div>
  );
}
